// Track fetch calls for assertions
const originalFetch = global.fetch
const fetchCalls: Array<{ url: string; init?: RequestInit }> = []

beforeEach(() => {
  vi.clearAllMocks()
  fetchCalls.length = 0

  global.fetch = vi.fn((input: RequestInfo | URL, init?: RequestInit) => {
    const url = typeof input === 'string' ? input : String(input)
    fetchCalls.push({ url, init })

    if (url === '/api/customers') {
      return Promise.resolve({
        ok: true,
        json: () => Promise.resolve({ customers: mockCustomers }),
      } as Response)
    }

    if (url.startsWith('/api/customers/') || url.startsWith('/api/repairs/customers/')) {
      const customerId = url.split('/').pop()
      const customer = mockCustomers.find(c => c.id === customerId)
      return Promise.resolve({
        ok: true,
        json: () => Promise.resolve({
          id: customer?.id,
          type: customer?.type,
          firstName: customer?.firstName,
          lastName: customer?.lastName,
          companyName: customer?.companyName,
          phone: customer?.phone,
          email: customer?.email,
          bicycles: mockBicycles,
        }),
      } as Response)
    }

    if (url === '/api/repairs') {
      return Promise.resolve({
        ok: true,
        json: () => Promise.resolve({ id: 'repair-001' }),
      } as Response)
    }

    return originalFetch(input, init)
  })
})

