/**
 * RepairCard — Standard-density card for the week calendar view.
 *
 * Shows: customer name, bicycle model, status badge (STATUS_COLORS),
 * assigned worker name, and pickup day indicator when applicable.
 * Card body click navigates to repair detail page.
 */

import { useNavigate } from 'react-router-dom'
import { User, Calendar } from 'lucide-react'
import type { RepairDetailWithCustomer } from '../types.js'
import { STATUS_COLORS } from '../types.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface WorkerOption {
  id: string
  name: string
}

interface RepairCardProps {
  repair: RepairDetailWithCustomer
  workers: WorkerOption[]
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function getWorkerName(assignedTo: string | null, workers: WorkerOption[]): string {
  if (!assignedTo) return 'Unassigned'
  const worker = workers.find((w) => w.id === assignedTo)
  return worker?.name ?? 'Unknown'
}

function formatStatus(status: RepairDetailWithCustomer['status']): string {
  return status.replace('_', ' ').replace(/\b\w/g, (c) => c.toUpperCase())
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function RepairCard({ repair, workers }: RepairCardProps) {
  const navigate = useNavigate()

  const handleClick = () => {
    navigate(`/repairs/${repair.id}`)
  }

  return (
    <div
      role="link"
      tabIndex={0}
      onClick={handleClick}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault()
          handleClick()
        }
      }}
      className={`group cursor-pointer rounded-lg border bg-card p-3 transition-colors hover:bg-muted/50 hover:border-primary/50 ${STATUS_COLORS[repair.status].split(' ')[0]}/10`}
    >
      {/* Status Badge */}
      <div className="mb-2">
        <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${STATUS_COLORS[repair.status]}`}>
          {formatStatus(repair.status)}
        </span>
      </div>

      {/* Customer Name */}
      <div className="text-sm font-semibold text-foreground mb-1">
        {repair.customerName || '—'}
      </div>

      {/* Bicycle Info */}
      <div className="text-xs text-muted-foreground mb-2">
        {repair.bicycleBrand} {repair.bicycleModel}
        {repair.bicycleColor ? ` · ${repair.bicycleColor}` : ''}
      </div>

      {/* Assigned Worker */}
      <div className="flex items-center gap-1.5 text-xs text-muted-foreground mb-2">
        <User size={12} />
        {getWorkerName(repair.assignedTo, workers)}
      </div>

      {/* Pickup Day Indicator */}
      {repair.pickupDate != null && (
        <div className="flex items-center gap-1.5 text-xs">
          <span className="inline-block w-2 h-2 rounded-full bg-blue-500" />
          <span className="text-muted-foreground flex items-center gap-1">
            <Calendar size={10} />
            pickup scheduled
          </span>
        </div>
      )}
    </div>
  )
}

